package org.atriasoft.archidata.api;

import org.atriasoft.archidata.annotation.apiGenerator.ApiDoc;
import org.atriasoft.archidata.tools.ConfigBaseVariable;

import jakarta.annotation.security.PermitAll;
import jakarta.ws.rs.GET;
import jakarta.ws.rs.NotFoundException;
import jakarta.ws.rs.Produces;
import jakarta.ws.rs.core.MediaType;

/**
 * JAX-RS resource that serves an embedded Swagger UI page backed by the OpenAPI specification
 * generated by {@link openApiResource}.
 *
 * <p>Disabled by default like the specification: it answers 404 unless {@code API_DOC_ENABLED=true}. The
 * Swagger UI files come from cdnjs with Subresource Integrity ({@code integrity} + {@code crossorigin}): a
 * modified file is not run by the browser.</p>
 */
public class SwaggerUiExternal extends openApiResource {

	/** Default constructor used by the JAX-RS resource framework. */
	public SwaggerUiExternal() {}

	/**
	 * Returns an HTML page embedding the Swagger UI, configured to load the OpenAPI spec from the sibling endpoint.
	 * @return An HTML string containing the Swagger UI page.
	 * @throws NotFoundException When {@code API_DOC_ENABLED} is not {@code true}.
	 */
	@GET
	@Produces(MediaType.TEXT_HTML)
	@PermitAll
	@ApiDoc(description = "Get the swagger UI", group = "DEVELOPEMENT")
	public String getSwaggerUI() {
		if (!ConfigBaseVariable.getApiDocEnabled()) {
			throw new NotFoundException("Not found");
		}
		return """
				<!DOCTYPE html>
				<html lang="en">
				<head>
				    <meta charset="UTF-8">
				    <meta name="viewport" content="width=device-width, initial-scale=1.0">
				    <title>Swagger UI</title>
				    <link rel="stylesheet" type="text/css" href="https://cdnjs.cloudflare.com/ajax/libs/swagger-ui/5.29.1/swagger-ui.css" integrity="sha512-eZpfl9qlKnbDvlJ2brfdx3nhlP1FMsA23w65motxKdYsUcfMcdO2bcLPr7mXhvyzmDZwuzYCJKrl/sEo1ditVQ==" crossorigin="anonymous" referrerpolicy="no-referrer" />
				</head>
				<body>
				    <div id="swagger-ui"></div>
				    <script src="https://cdnjs.cloudflare.com/ajax/libs/swagger-ui/5.29.1/swagger-ui-bundle.js" integrity="sha512-iDdi6WwSTimAFh1NhPyFZpHJWr16m/PupHztElqQL+gQoQDavUATsP9hcvgs9Yci+EUA//WvZYZsCTDhRDKc3g==" crossorigin="anonymous" referrerpolicy="no-referrer"></script>
				    <script src="https://cdnjs.cloudflare.com/ajax/libs/swagger-ui/5.29.1/swagger-ui-standalone-preset.js" integrity="sha512-oGq+mP+3XUyYDm9vsprsd6YdhOokdkcLNUZnmEE6HJzG0F9fIaB8kgGZsjdfTWN8w/1f2kN4a/0xkla0hsetcQ==" crossorigin="anonymous" referrerpolicy="no-referrer"></script>
				    <script>
				        window.onload = function() {
				            const ui = SwaggerUIBundle({
				                url: "openapi/swagger.json",
				                dom_id: '#swagger-ui',
				                presets: [
				                    SwaggerUIBundle.presets.apis,
				                    SwaggerUIStandalonePreset
				                ],
				                layout: 'BaseLayout',
				                deepLinking: true,
				            })
						}
				    </script>
				</body>
				</html>""";
	}
}
